CREATE TABLE farm_plots(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`farm_id` bigint  NOT NULL,`plot_name` varchar(255)  NOT NULL,`area` DECIMAL(10,2)  NOT NULL COMMENT 'Area in acres',`soil_type` varchar(255)  NOT NULL COMMENT 'Clay, Sandy, Loamy',`irrigation_type` varchar(255)  NOT NULL COMMENT 'Rain-fed, Canal, Borewell, Mixed',`state` varchar(255)  NOT NULL,`district` varchar(255)  NOT NULL,`previous_crops` varchar(255)  NULL COMMENT 'JSON array of previous crops',`investment_capacity` DECIMAL(12,2)  NULL COMMENT 'Budget per acre')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;